using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Threading.Tasks;using System.Security.Cryptography;using UnityEngine;using UnityEngine.UI;using HabitatIsland;
public static class Feedback221708Checks
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;const string Dir="Verification/feedback-221708";
 static HabitatGame g;static StringBuilder log;static int count;static object Call(string name,params object[] a)=>typeof(HabitatGame).GetMethod(name,F).Invoke(g,a);
 static void Check(bool v,string s){log.AppendLine((v?"PASS ":"FAIL ")+s);File.WriteAllText(Dir+"/runtime.txt",log.ToString());if(!v)throw new Exception(s);count++;}
 static async Task Frames(int n=3){int until=Time.frameCount+n;double end=Time.realtimeSinceStartupAsDouble+20;while(Time.frameCount<until){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("frames stalled");await Task.Delay(12);}}
 static async Task Until(Func<bool> done,string s,double seconds=90){double end=Time.realtimeSinceStartupAsDouble+seconds;while(!done()){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("timeout "+s);await Frames(1);}}
 static string Hashes(string p){using(var sha=SHA256.Create())return !Directory.Exists(p)?"":string.Join("\n",Directory.GetFiles(p,"*",SearchOption.AllDirectories).OrderBy(x=>x).Select(x=>x+Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(x)))));}
 static async Task Shot(string name){await Frames(5);ScreenCapture.CaptureScreenshot(Path.GetFullPath(Dir+"/"+name+".png"));await Frames(8);}
 static HabitatState Pond(){var s=HabitatLevels.Create(8);s.width=7;s.depth=5;s.tiles=Enumerable.Range(0,35).Select(i=>new Tile{height=1}).ToArray();s.animals.Clear();s.playerX=3;s.playerZ=1;s.onHarbor=false;s.rod=s.specialRod=s.backBasketUnlocked=true;s.won=false;s.waterLevel=0;s.tiles[2*7+2].height=0;s.animals.Add(new Animal{id=1,x=2,z=2,species=Species.Goldfish});s.animals.Add(new Animal{id=2,x=4,z=2,species=Species.Jellyfish});return s;}
 public static async Task<string> Run()
 {
  Directory.CreateDirectory(Dir);log=new StringBuilder();g=HabitatGame.Instance;if(!g||!Application.isPlaying)throw new Exception("Play required");
  var sf=typeof(HabitatGame).GetField("SaveSlotDirectoryForTests",BindingFlags.Static|BindingFlags.NonPublic);object old=sf.GetValue(null);string real=Path.Combine(Application.persistentDataPath,"Playtests"),hash=Hashes(real);sf.SetValue(null,Path.GetFullPath(Dir+"/isolated-"+DateTime.Now.ToString("HHmmssfff")));
  object snapshot=Call("CaptureSnapshot");bool paused=g.paused,session=g.SessionStarted;int tool=g.tool;
