   g.NewSession();await Until(()=>g.Story.IsCgPlaying&&g.Story.CgPlayer.isPrepared,"opening prepare");Check(g.Story.CurrentCg=="cg00","new game launches delivered cg00");Check(!g.State.openingCompleted,"opening remains uncommitted during CG");await Until(()=>g.Story.CgPlayer.frame>2,"opening frames");Check(g.Story.CgPlayer.audioTrackCount>0,"CG uses embedded audio track");await Shot("opening-cg00");
   g.Story.TogglePause();double t=g.Story.CgPlayer.time;await Frames(24);Check(g.Story.IsPaused&&Math.Abs(g.Story.CgPlayer.time-t)<.1,"pause freezes video and audio");g.Story.TogglePause();await Until(()=>!g.StoryPlaying,"opening natural finish");Check(g.State.openingCompleted,"natural opening commits journey");int day=g.State.day;Check(!g.Story.Skip()&&g.State.day==day,"ended opening cannot commit twice");g.Hud.ClosePanels();await Frames();g.Hud.ClosePanels();
   Check(!g.View.Harbor.ModelTransform.GetComponentInChildren<HabitatHomeIsland>(true),"home has no block island or access plank");g.View.FocusPlayer();await Frames(35);Check(g.View.GameCamera.orthographicSize<5,"home camera closer than old 6.5");await Shot("home-dock");
   g.State.harborX=500;g.State.harborZ=500;var recovered=g.View.Harbor.WorldPosition(g.State);Check(g.State.onHarbor&&Math.Abs(g.State.harborX)<100,"old off-deck coordinates safely recover");
   for(int i=1;i<8;i++){Check(!g.HasTool(i),"new game owns no tool "+i);Check(!g.TrySelectTool(i)&&g.tool==0,"unowned selection rejected "+i);}
   g.State.shovels=1;g.State.magnets=1;g.State.launchers=1;g.State.rod=true;g.State.traps=1;g.State.cargo=1;for(int i=0;i<8;i++)Check(g.TrySelectTool(i),"owned selection accepted "+i);g.tool=0;
   var s=Pond();var fish=s.animals[0];Check(HabitatRules.Evaluate(s,fish,g.tuning).suitable,"fixture fish suitable");Check(!HabitatRules.Evaluate(s,s.animals[1],g.tuning).suitable,"fixture other animal unsuitable");Check(HabitatRules.CanHarvest(s,fish,g.tuning,out _),"partial completion allows fish harvest");Check(HabitatRules.Fish(s,2,2,Species.Goldfish,g.tuning)&&s.fish==1&&s.animals.Count==2,"mid-level harvest retains parents and rewards once");Check(!HabitatRules.Fish(s,2,2,Species.Goldfish,g.tuning),"duplicate catch rejected");Check(!HabitatMechanicLevels.CompleteHabitat(s,g.tuning)&&!s.won,"partial harvest cannot clear level");Check(!HabitatRules.CanHarvest(s,s.animals[1],g.tuning,out _),"unsuitable target cannot harvest");
   s.tiles[2*7+4].height=0;for(int x=4;x<7;x++)s.tiles[2*7+x].height=0;Check(HabitatMechanicLevels.CompleteHabitat(s,g.tuning)&&s.won,"all residents suitable clears level");
   var raft=Pond();raft.animals.Clear();raft.width=9;raft.depth=3;raft.tiles=Enumerable.Range(0,27).Select(i=>new Tile{height=0}).ToArray();raft.tiles[1*9+7].height=1;raft.playerX=1;raft.playerZ=1;raft.tiles[10].prop=PropKind.Raft;raft.tiles[10].rotation=1;
   Check(HabitatRules.MovePlayer(raft,1,0,false,g.tuning)&&raft.playerX==6,"one input slides to before land obstacle");Check(HabitatRules.MovePlayer(raft,-1,0,false,g.tuning)&&raft.playerX==0,"reverse slides to map edge");raft.tiles[3+9].prop=PropKind.Float;Check(HabitatRules.MovePlayer(raft,1,0,false,g.tuning)&&raft.playerX==2,"floating box stops raft without merging");Check(raft.tiles[3+9].prop==PropKind.Float,"blocking box preserved");
   raft.tiles[3+9].prop=PropKind.None;raft.playerX=1;raft.tiles[2+9].prop=PropKind.None;raft.tiles[1+9].prop=PropKind.Raft;g.LoadLevel(8);g.paused=true;g.State=raft;g.View.Initialize(g.State);g.Hud.ClosePanels();await Frames();int actions=g.ActionCount;g.Move(1,0,false);Check(g.Busy&&g.State.playerX==1,"raft authoritative position stays at departure during motion");await Frames(20);Check(g.State.playerX==1,"long slide not committed early");await Until(()=>!g.Busy,"raft arrival");Check(g.State.playerX==6&&g.ActionCount==actions+1,"whole slide commits one action after visual arrival");g.Undo();Check(g.State.playerX==1&&HabitatRules.TileAt(g.State,1,1).prop==PropKind.Raft,"undo restores raft and rider");g.Move(1,0,false);await Frames(10);Call("CancelPendingAction");Check(g.State.playerX==1&&!g.Busy,"cancel long raft trip preserves source");
   g.LoadLevel(8);g.paused=true;g.State=Pond();g.View.Initialize(g.State);g.Hud.ClosePanels();g.tool=4;await Frames(12);Check(g.Fishing.Begin(g,2,2),"partial-goal live fishing begins");await Frames(20);Check(g.View.PlayerVisual.ActiveEquipmentKind=="Rod","rod visible while casting");g.Fishing.Cancel(false);await Frames(12);Check(g.View.PlayerVisual.ActiveEquipmentKind!="Rod","rod stowed on cancellation");int before=g.State.fish;g.CompleteFishing(2,2,Species.Goldfish,1);Check(g.FishingLanding&&g.State.fish==before,"partial-goal landing reward deferred");await Until(()=>!g.Busy,"fishing landing");Check(g.State.fish==before+1&&!g.State.won,"live landing commits only catch, not unfinished level");await Frames(12);Check(g.View.PlayerVisual.ActiveEquipmentKind!="Rod","rod stowed after landing");
   g.LoadLevel(5);g.paused=true;g.State.won=true;g.State.firstClearCgSeen=false;g.Hud.ClosePanels();await Until(()=>g.Story.IsCgPlaying,"first clear hook");Check(g.Story.CurrentCg=="cg01"&&!g.State.firstClearCgSeen,"first level clear launches cg01 before marking seen");await Until(()=>g.Story.CgPlayer.frame>2,"cg01 frames");await Shot("first-clear-cg01");await Until(()=>!g.StoryPlaying,"cg01 natural finish");Check(g.State.firstClearCgSeen,"cg01 marked after natural completion");await Frames(15);Check(!g.StoryPlaying,"cg01 does not replay each frame");
   g.LoadLevel(HabitatLevels.HomeHarborIndex);g.paused=true;g.Hud.ClosePanels();g.View.Harbor.TryPlaceAt(g.State,HabitatImportedDockLayout.HomeApproach);day=g.State.day;g.RestAtHome();Check(g.Story.CurrentCg=="cg03"&&g.State.day==day,"home launches cg03 before day advance");await Until(()=>g.Story.CgPlayer.frame>2,"cg03 frames");await Shot("home-cg03");await Until(()=>!g.StoryPlaying,"cg03 natural finish");Check(g.State.day==day+1,"home CG advances exactly one day");Check(!g.Story.Skip()&&g.State.day==day+1,"repeated skip cannot advance day");
   g.Hud.ClosePanels();int calls=0;Check(g.Story.BeginCg("cg01",()=>calls++),"CG cancellation fixture begins");await Until(()=>g.Story.CgPlayer.isPrepared,"cancel prepare");g.Story.Cancel();await Frames(3);Check(calls==0&&!g.StoryPlaying,"cancel discards CG callback");g.Story.BeginCg("cg01",()=>calls++);g.Story.Skip();g.Story.Skip();Check(calls==1&&!g.StoryPlaying,"skip completes only once even before preparation");
   return "PASS "+count+" checks; controlled gameplay/CG fixtures, not full campaign.";
  }
  finally
  {
   g.Story.Cancel();Call("CancelPendingAction");if(g.Fishing)g.Fishing.Cancel(false);Call("RestoreSnapshot",snapshot);g.paused=paused;g.tool=tool;typeof(HabitatGame).GetProperty("SessionStarted").SetValue(g,session);g.Hud.ClosePanels();sf.SetValue(null,old);Check(Hashes(real)==hash,"real player saves SHA256 unchanged");File.WriteAllText(Dir+"/runtime.txt",log.ToString());
  }
 }
